import os, sys
from openpyxl import load_workbook

target = sys.argv[1] if len(sys.argv) > 1 else "budget.xlsx"
cands = [target, os.path.abspath(target), os.path.join(os.path.dirname(os.path.abspath(__file__)), target)]
path = next((c for c in cands if os.path.exists(c)), None)
if path is None:
    print("NOT FOUND:", target, "cwd:", os.getcwd())
    sys.exit(0)
print("FOUND:", path)

wb_form = load_workbook(path, data_only=False)
wb_val = load_workbook(path, data_only=True)
for ws in wb_form.worksheets:
    print("SHEET:", ws.title, "max_row:", ws.max_row, "max_col:", ws.max_column)
    wsv = wb_val[ws.title]
    for row in ws.iter_rows():
        for c in row:
            v = c.value
            if v is not None:
                cached = wsv[c.coordinate].value
                if isinstance(v, str) and v.startswith("="):
                    print(c.coordinate, "FORMULA", v, "CACHED", repr(cached))
                else:
                    print(c.coordinate, repr(v))
    if ws.merged_cells.ranges:
        print("MERGED:", [str(r) for r in ws.merged_cells.ranges])

