from openpyxl import load_workbook

PATH = "budget.xlsx"
wbv = load_workbook(PATH, data_only=True)
wbf = load_workbook(PATH, data_only=False)

def fmt(v):
    if v is None:
        return ""
    if isinstance(v, float) and v.is_integer():
        return int(v)
    return v

for wsv, wsf in zip(wbv.worksheets, wbf.worksheets):
    print("SHEET:", wsv.title, "rows:", wsv.max_row, "cols:", wsv.max_column)
    for r in range(1, wsv.max_row + 1):
        out = []
        for c in range(1, wsv.max_column + 1):
            v = fmt(wsv.cell(row=r, column=c).value)
            f = wsf.cell(row=r, column=c).value
            if isinstance(f, str) and f.startswith("="):
                out.append(f"{v}[{f}]")
            else:
                out.append("" if v == "" else v)
        if any(x != "" for x in out):
            print("R" + str(r), out)

    nums = []
    for r in range(1, wsv.max_row + 1):
        for c in range(1, wsv.max_column + 1):
            v = wsv.cell(row=r, column=c).value
            if isinstance(v, (int, float)):
                nums.append((r, c, v))
    print("numeric_cells:", nums)
    print("grand_sum_all_numeric:", sum(v for _, _, v in nums))
    by_col = {}
    for r, c, v in nums:
        by_col.setdefault(c, []).append((r, v))
    for c in sorted(by_col):
        print("column", c, "sum:", sum(v for _, v in by_col[c]))

